<script setup lang="ts">defineProps<{modelValue:number;pages:number}>();const emit=defineEmits<{'update:modelValue':[v:number]}>();</script><template><nav aria-label="Pagination" class="vx-pagination"><button :disabled="modelValue<=1" @click="emit('update:modelValue',modelValue-1)">Previous</button><span>Page {{modelValue}} of {{pages}}</span><button :disabled="modelValue>=pages" @click="emit('update:modelValue',modelValue+1)">Next</button></nav></template>